/* ============================================================
 * Smart Excel - Official French commune database
 * Reference: geo.api.gouv.fr (IGN / data.gouv.fr), Licence Ouverte 2.0,
 * the official INSEE code of every commune and its postal codes
 * (js/data/communes.js, generated by test/tools/build-communes.js).
 *
 * Rules enforced here:
 *  - a city is CORRECTED only when the identification is certain
 *    (unique commune name, accent/spacing/case/hyphen variants, a known
 *    misspelling, or a postal code that points to a single commune);
 *  - when the commune cannot be identified, the Ville stays EMPTY;
 *  - a city is never invented.
 * ============================================================ */
(function (root) {
  'use strict';
  var SEC = (root.SEC = root.SEC || {});

  /* ---------- Text keys ---------- */

  function stripAccents(s) {
    return String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }

  /* Matching key: no accents, no case, no punctuation, no spaces.
   * "Saint-Denis" / "SAINT DENIS" / "saintdenis" -> "saintdenis". */
  function key(s) {
    return stripAccents(s).toLowerCase().replace(/[^a-z0-9]/g, '');
  }

  /* Words ignored when comparing a city written with a different spacing
   * or an extra article ("L Isle sur la Sorgue" vs "L'Isle-sur-la-Sorgue"). */
  var ARTICLE_RE = /^(?:l|d|de|du|des|la|le|les|st|ste|sainte)$/;

  /* "Saint" / "Sainte" / "St" / "Ste" spellings of the same commune. */
  function saintKey(k) {
    return k.replace(/^saint/, 'st').replace(/^sainte/, 'ste');
  }

  /* ---------- Database ---------- */

  var built = null;   // lazily built index

  function normalizeName(name) {
    return String(name || '').replace(/[’´`]/g, "'").replace(/\s+/g, ' ').trim();
  }

  /* Official spelling: "L'ISLE-SUR-LA-SORGUE" -> "L'Isle-sur-la-Sorgue",
   * "BERRE L'ETANG" -> "Berre-l'Étang" (Étang is a common word), while
   * "SAINT DENIS" stays "Saint-Denis". Only apostrophes and hyphens are
   * normalised; letters are never changed (never invent a spelling). */
  var LOWER_WORDS = { sur: 1, sous: 1, de: 1, du: 1, des: 1, la: 1, le: 1, les: 1, en: 1, et: 1, aux: 1, au: 1, d: 1, l: 1, 'lès': 1, 'lés': 1, pres: 1, 'près': 1 };

  function displayName(name) {
    var s = normalizeName(name);
    /* One case only: lower-case letters mixed with capitals (SHOUTING or
     * all lower-case input) -> conventional capitalisation. */
    var hasLower = /[a-zà-ÿ]/.test(s);
    var hasUpper = /[A-ZÀ-Ÿ]/.test(s);
    if (hasLower && hasUpper) return s;
    var words = s.toLowerCase().split(/([\s'\-])/);
    var out = '';
    var atWordStart = true;
    for (var i = 0; i < words.length; i++) {
      var w = words[i];
      if (/^[\s'\-]$/.test(w)) {
        out += w;
        atWordStart = true;
        continue;
      }
      if (LOWER_WORDS[w] && !atWordStart) {
        out += w;
      } else {
        out += w.charAt(0).toUpperCase() + w.slice(1);
      }
      atWordStart = false;
    }
    /* "L'Isle" / "D'Artagnan": the elided article keeps its capital and the
     * following letter is the normal capital of the word. */
    out = out.replace(/(^|[\s\-])([LDS])'([a-zà-ÿ])/g, function (m, pre, el, ch) {
      return pre + el.toUpperCase() + "'" + ch.toUpperCase();
    });
    return out;
  }

  /* "L'Isle-sur-la-Sorgue" and "L Isle sur la Sorgue" and "LislesurlaSorgue"
   * must all resolve to the same commune: compare the significant words. */
  function looseKey(name) {
    var words = stripAccents(normalizeName(name)).toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
    var kept = [];
    words.forEach(function (w, i) {
      if (i > 0 && ARTICLE_RE.test(w)) return;
      kept.push(w);
    });
    return saintKey(kept.join(''));
  }

  /* Small, explicit list of frequent misspellings found in French customer
   * files. Each entry is an UNAMBIGUOUS commune (unique name, checked against
   * the official database when it is built). A misspelling is only accepted
   * when one single commune has the corresponding official name. */
  var INITIAL_ALIASES = {
    marseilles: '13055', marsseille: '13055', marseile: '13055', marseillle: '13055',
    lyonn: '69123', lione: '69123', tolouse: '31555', toulouses: '31555',
    bordeau: '33063', bordaux: '33063', bordeax: '33063',
    nante: '44109', nantes: '44109', renne: '35238', liles: '59350',
    lile: '59350', lilee: '59350', strabourg: '67482', stasbourg: '67482',
    nisse: '06088', nices: '06088', grenobles: '38185', dijons: '21231',
    reim: '51454', rheims: '51454', clermond: '63113',
    montpelier: '34172', montpelliers: '34172', limoge: '87085',
    havrais: '76351', tour: '37261', ange: '49007'
  };
  var ALIASES = null;   // initialised after the database index exists

  function build() {
    if (built) return built;
    var byKey = Object.create(null);       // name key -> [entry]
    var byLoose = Object.create(null);     // loose key -> [entry]
    var byInsee = Object.create(null);
    var cpMap = Object.create(null);       // postal code -> [insee]
    var raw = typeof SEC.COMMUNE_DB === 'string' ? SEC.COMMUNE_DB : '';
    raw.split('\n').forEach(function (line) {
      if (!line) return;
      var parts = line.split('\t');
      if (parts.length < 2) return;
      var entry = {
        nom: normalizeName(parts[0]),
        display: displayName(parts[0]),
        insee: parts[1],
        cps: parts[2] ? parts[2].split(',').filter(Boolean) : []
      };
      if (!entry.nom || byInsee[entry.insee]) return;
      byInsee[entry.insee] = entry;
      var k = key(entry.nom);
      (byKey[k] || (byKey[k] = [])).push(entry);
      var lk = looseKey(entry.nom);
      (byLoose[lk] || (byLoose[lk] = [])).push(entry);
      entry.cps.forEach(function (cp) {
        var list = cpMap[cp] || (cpMap[cp] = []);
        if (list.indexOf(entry.insee) === -1) list.push(entry.insee);
      });
    });
    /* Keep a misspelling only when it is not itself a real commune and the
     * commune it targets carries a unique official name: never invent. */
    ALIASES = Object.create(null);
    Object.keys(INITIAL_ALIASES).forEach(function (miss) {
      var target = byInsee[INITIAL_ALIASES[miss]];
      if (!target) return;
      if (byKey[miss]) return;                     // a real commune has this name
      var sameName = byKey[key(target.nom)] || [];
      if (sameName.length !== 1) return;
      ALIASES[miss] = INITIAL_ALIASES[miss];
    });
    built = { byKey: byKey, byLoose: byLoose, byInsee: byInsee, cpMap: cpMap };
    return built;
  }

  function unique(list) {
    return list && list.length === 1 ? list[0] : null;
  }

  function communeByInsee(insee) {
    return build().byInsee[insee] || null;
  }

  /* Communes attached to a postal code (used for suggestions only). */
  function communesForPostal(cp) {
    var idx = build();
    var cps = String(cp || '').trim().toUpperCase().replace(/[\s\-]/g, '');
    if (!/^\d{5}$/.test(cps) && !/^2[AB]\d{3}$/.test(cps)) return [];
    return (idx.cpMap[cps] || []).map(function (insee) { return idx.byInsee[insee]; });
  }

  /* A real French postal code: 5 digits, or 2A/2B + 3 digits (Corsica). */
  function isPostalValid(cp) {
    var cps = String(cp || '').trim().toUpperCase();
    if (!/^\d{5}$/.test(cps) && !/^2[AB]\d{3}$/.test(cps)) return false;
    return !!build().cpMap[cps];
  }

  /* Look a city name up. Returns { entry, confidence } or null.
   * confidence: 'certain' (unique commune) or 'ambiguous'. */
  function lookupName(name) {
    var idx = build();
    var s = normalizeName(name);
    if (!s || /\d/.test(s)) return null;
    var k = key(s);
    if (!k) return null;

    var hit = unique(idx.byKey[k]);
    if (hit) return { entry: hit, confidence: 'certain', how: 'name' };

    var alias = ALIASES[k];
    if (alias && idx.byInsee[alias]) return { entry: idx.byInsee[alias], confidence: 'certain', how: 'alias' };

    var lk = looseKey(s);
    hit = unique(idx.byLoose[lk]);
    if (hit) return { entry: hit, confidence: 'certain', how: 'name-variant' };

    /* Several communes share this exact name ("Saint-Denis" in 93, 97, …):
     * reported as ambiguous, a postal code may still decide. */
    var list = idx.byKey[k];
    if (list && list.length > 1) return { entry: null, confidence: 'ambiguous', how: 'name', candidates: list };

    /* Spacing/hyphen variant shared by several communes: only one of them is
     * then designated by the postal code; ambiguous otherwise. */
    var loose = idx.byLoose[lk];
    if (loose && loose.length > 1) return { entry: null, confidence: 'ambiguous', how: 'name-variant', candidates: loose };
    return null;
  }

  /* Identify the commune from a postal code, and only when the postal code
   * belongs to a SINGLE commune ("31000" -> Toulouse). A code shared by
   * several communes ("75001" ... belong to Paris only; "97100" is not)
   * proves nothing and returns null. */
  function lookupPostal(cp) {
    var list = communesForPostal(cp);
    if (list.length === 1) return list[0];
    return null;
  }

  /* Among communes sharing one name, the one whose postal codes include the
   * given code (and only that one). */
  function designatedCandidate(list, cp) {
    var matching = (list || []).filter(function (e) { return e.cps.indexOf(cp) !== -1; });
    return matching.length === 1 ? matching[0] : null;
  }

  /* The written name and the commune found from the postal code must share
   * an obvious textual link before the commune name is used. */
  function compatible(written, entry) {
    var a = key(written);
    var b = key(entry.nom);
    if (!a || !b) return false;
    if (a === b) return true;
    if (a.charAt(0) !== b.charAt(0)) return false;
    if (a.indexOf(b) !== -1 || b.indexOf(a) !== -1) return true;
    /* "Bellegarde" + 01200 -> "Valserhône": one of the words of the official
     * name is the written name. */
    return b.split(' ').some(function (w) { return w.length >= 4 && w === a; });
  }

  /* Main entry point.
   *   validate(rawCity, rawPostal) ->
   *     { value, status, postal, official, insee }
   *   status:
   *     'ok'         official spelling kept
   *     'corrected'  confidently corrected (accents / spacing / typo / cp)
   *     'ambiguous'  several communes fit -> Ville left EMPTY
   *     'unknown'    no commune found -> Ville left EMPTY
   *     'empty'      nothing to validate
   * The returned value is ALWAYS the official name of a real commune,
   * never a guess. */
  function validate(rawCity, rawPostal) {
    var city = normalizeName(rawCity);
    var cp = String(rawPostal == null ? '' : rawPostal).trim().toUpperCase().replace(/[\s\-]/g, '');
    if (!/^\d{5}$/.test(cp) && !/^2[AB]\d{3}$/.test(cp)) cp = '';
    var postalEntry = cp ? lookupPostal(cp) : null;

    if (!city) {
      return { value: '', status: 'empty', postal: cp, official: postalEntry ? postalEntry.display : '', insee: postalEntry ? postalEntry.insee : '' };
    }

    var found = lookupName(city);
    if (found && found.entry) {
      var e = found.entry;
      /* A name that is unique in France is a certain identification, even when
       * the postal code is wrong (the commune stays the source of truth). */
      if (e.display === city) return { value: city, status: 'ok', postal: cp, official: e.display, insee: e.insee };
      return { value: e.display, status: 'corrected', postal: cp, official: e.display, insee: e.insee };
    }

    /* Several communes share this name: the postal code decides when it
     * designates exactly one of the candidates. */
    if (found && found.confidence === 'ambiguous') {
      var pick = cp ? designatedCandidate(found.candidates, cp) : null;
      if (pick) return { value: pick.display, status: 'corrected', postal: cp, official: pick.display, insee: pick.insee };
      return { value: '', status: 'ambiguous', postal: cp, official: '', insee: '' };
    }

    /* Name not identifiable: the postal code alone can identify the commune
     * (a code that belongs to one single commune), but it must be COMPATIBLE
     * with the written name — same first letter, or one name contained in
     * the other ("Bellegarde" + 01200 -> Bellegarde-sur-Valserine). Anything
     * else would be an invention. */
    if (postalEntry && compatible(city, postalEntry)) {
      return { value: postalEntry.display, status: 'corrected', postal: cp, official: postalEntry.display, insee: postalEntry.insee };
    }
    return { value: '', status: 'unknown', postal: cp, official: '', insee: '' };
  }

  var communeCount = null;

  /* Does the value look like a commune name (used by the value analyzer)? */
  function isKnownCity(name) {
    var found = lookupName(name);
    return !!(found && found.entry);
  }

  SEC.Communes = {
    version: function () { return SEC.COMMUNE_DB_VERSION || ''; },
    /* Counted ONCE: this is called for every row, and rebuilding the key list
     * of the whole INSEE database each time cost 90 % of a batch's CPU. */
    count: function () {
      if (communeCount === null) communeCount = Object.keys(build().byInsee).length;
      return communeCount;
    },
    key: key,
    displayName: displayName,
    lookupName: lookupName,
    lookupPostal: lookupPostal,
    communeByInsee: communeByInsee,
    communesForPostal: communesForPostal,
    isPostalValid: isPostalValid,
    isKnownCity: isKnownCity,
    validate: validate
  };
})(typeof self !== 'undefined' ? self : globalThis);
